const A=require('../server-data/accounts.cjs'),S=require('../server-data/subjects.cjs'),G=require('../server-data/guided-review.cjs');const cards=[...require('../server-data/question-bank.json').cards.map(c=>({...c,subject:'termicas'})),...require('../server-data/visual-bank.json').cards.map(c=>({...c,subject:'termicas'})),...require('../server-data/course-bank.json').cards,...require('../server-data/course-visual-bank.json').cards];module.exports=async(req,res)=>{try{A.guard(req,res);if(req.method!=='POST')return res.status(405).json({error:'Método no permitido.'});const b=typeof req.body==='string'?JSON.parse(req.body):req.body||{};if(!S.valid(b.subject))return res.status(400).json({error:'Materia inválida.'});if(b.action==='lesson'){const lesson=G.lesson(b.subject,b.unit);return lesson?res.status(200).json(lesson):res.status(404).json({error:'Tema no encontrado.'})}const card=cards.find(c=>c.id===b.id&&c.subject===b.subject);if(!card)return res.status(404).json({error:'Pregunta no encontrada.'});return res.status(200).json({answer:card.normal.answer,sources:card.sources.map(r=>r.url?r:{...r,url:undefined}),visual:card.visual||null})}catch(e){return A.error(res,e)}};
